INSERT INTO verses (translation_id, book_id, chapter, verse, text, words_of_jesus) VALUES
('bsb','GEN',1,1,'In the beginning God created the heavens and the earth.',NULL),
('bsb','GEN',1,2,'Now the earth was formless and void, and darkness was over the surface of the deep. And the Spirit of God was hovering over the surface of the waters.',NULL),
('bsb','GEN',1,3,'And God said, “Let there be light,” and there was light.',NULL),
('bsb','GEN',1,4,'And God saw that the light was good, and He separated the light from the darkness.',NULL),
('bsb','GEN',1,5,'God called the light “day,” and the darkness He called “night.” And there was evening, and there was morning—the first day.',NULL),
('bsb','GEN',1,6,'And God said, “Let there be an expanse between the waters, to separate the waters from the waters.”',NULL),
('bsb','GEN',1,7,'So God made the expanse and separated the waters beneath it from the waters above. And it was so.',NULL),
('bsb','GEN',1,8,'God called the expanse “sky.” And there was evening, and there was morning—the second day.',NULL),
('bsb','GEN',1,9,'And God said, “Let the waters under the sky be gathered into one place, so that the dry land may appear.” And it was so.',NULL),
('bsb','GEN',1,10,'God called the dry land “earth,” and the gathering of waters He called “seas.” And God saw that it was good.',NULL),
('bsb','GEN',1,11,'Then God said, “Let the earth bring forth vegetation: seed-bearing plants and fruit trees, each bearing fruit with seed according to its kind.” And it was so.',NULL),
('bsb','GEN',1,12,'The earth produced vegetation: seed-bearing plants according to their kinds and trees bearing fruit with seed according to their kinds. And God saw that it was good.',NULL),
('bsb','GEN',1,13,'And there was evening, and there was morning—the third day.',NULL),
('bsb','GEN',1,14,'And God said, “Let there be lights in the expanse of the sky to distinguish between the day and the night, and let them be signs to mark the seasons and days and years.',NULL),
('bsb','GEN',1,15,'And let them serve as lights in the expanse of the sky to shine upon the earth.” And it was so.',NULL),
('bsb','GEN',1,16,'God made two great lights: the greater light to rule the day and the lesser light to rule the night. And He made the stars as well.',NULL),
('bsb','GEN',1,17,'God set these lights in the expanse of the sky to shine upon the earth,',NULL),
('bsb','GEN',1,18,'to preside over the day and the night, and to separate the light from the darkness. And God saw that it was good.',NULL),
('bsb','GEN',1,19,'And there was evening, and there was morning—the fourth day.',NULL),
('bsb','GEN',1,20,'And God said, “Let the waters teem with living creatures, and let birds fly above the earth in the open expanse of the sky.”',NULL),
('bsb','GEN',1,21,'So God created the great sea creatures and every living thing that moves, with which the waters teemed according to their kinds, and every bird of flight after its kind. And God saw that it was good.',NULL),
('bsb','GEN',1,22,'Then God blessed them and said, “Be fruitful and multiply and fill the waters of the seas, and let birds multiply on the earth.”',NULL),
('bsb','GEN',1,23,'And there was evening, and there was morning—the fifth day.',NULL),
('bsb','GEN',1,24,'And God said, “Let the earth bring forth living creatures according to their kinds: livestock, land crawlers, and beasts of the earth according to their kinds.” And it was so.',NULL),
('bsb','GEN',1,25,'God made the beasts of the earth according to their kinds, the livestock according to their kinds, and everything that crawls upon the earth according to its kind. And God saw that it was good.',NULL),
('bsb','GEN',1,26,'Then God said, “Let Us make man in Our image, after Our likeness, to rule over the fish of the sea and the birds of the air, over the livestock, and over all the earth itself and every creature that crawls upon it.”',NULL),
('bsb','GEN',1,27,'So God created man in His own image; in the image of God He created him; male and female He created them.',NULL),
('bsb','GEN',1,28,'God blessed them and said to them, “Be fruitful and multiply, and fill the earth and subdue it; rule over the fish of the sea and the birds of the air and every creature that crawls upon the earth.”',NULL),
('bsb','GEN',1,29,'Then God said, “Behold, I have given you every seed-bearing plant on the face of all the earth, and every tree whose fruit contains seed. They will be yours for food.',NULL),
('bsb','GEN',1,30,'And to every beast of the earth and every bird of the air and every creature that crawls upon the earth—everything that has the breath of life in it—I have given every green plant for food.” And it was so.',NULL),
('bsb','GEN',1,31,'And God looked upon all that He had made, and indeed, it was very good. And there was evening, and there was morning—the sixth day.',NULL),
('bsb','PSA',23,1,'The LORD is my shepherd; I shall not want.',NULL),
('bsb','PSA',23,2,'He makes me lie down in green pastures; He leads me beside quiet waters.',NULL),
('bsb','PSA',23,3,'He restores my soul; He guides me in the paths of righteousness for the sake of His name.',NULL),
('bsb','PSA',23,4,'Even though I walk through the valley of the shadow of death, I will fear no evil, for You are with me; Your rod and Your staff, they comfort me.',NULL),
('bsb','PSA',23,5,'You prepare a table before me in the presence of my enemies. You anoint my head with oil; my cup overflows.',NULL),
('bsb','PSA',23,6,'Surely goodness and mercy will follow me all the days of my life, and I will dwell in the house of the LORD forever.',NULL),
('bsb','PSA',117,1,'Praise the LORD, all you nations! Extol Him, all you peoples!',NULL),
('bsb','PSA',117,2,'For great is His loving devotion toward us, and the faithfulness of the LORD endures forever. Hallelujah!',NULL),
('bsb','MAT',11,1,'After Jesus had finished instructing His twelve disciples, He went on from there to teach and preach in their cities.',NULL),
('bsb','MAT',11,2,'Meanwhile John heard in prison about the works of Christ, and he sent his disciples',NULL),
('bsb','MAT',11,3,'to ask Him, “Are You the One who was to come, or should we look for someone else?”',NULL),
('bsb','MAT',11,4,'Jesus replied, “Go back and report to John what you hear and see:',NULL),
('bsb','MAT',11,5,'The blind receive sight, the lame walk, the lepers are cleansed, the deaf hear, the dead are raised, and the good news is preached to the poor.',NULL),
('bsb','MAT',11,6,'Blessed is the one who does not fall away on account of Me.”',NULL),
('bsb','MAT',11,7,'As John’s disciples were leaving, Jesus began to speak to the crowds about John: “What did you go out into the wilderness to see? A reed swaying in the wind?',NULL),
('bsb','MAT',11,8,'Otherwise, what did you go out to see? A man dressed in fine clothes? Look, those who wear fine clothing are found in kings’ palaces.',NULL),
('bsb','MAT',11,9,'What then did you go out to see? A prophet? Yes, I tell you, and more than a prophet.',NULL),
('bsb','MAT',11,10,'This is the one about whom it is written: ‘Behold, I will send My messenger ahead of You, who will prepare Your way before You.’',NULL),
('bsb','MAT',11,11,'Truly I tell you, among those born of women there has risen no one greater than John the Baptist. Yet even the least in the kingdom of heaven is greater than he.',NULL),
('bsb','MAT',11,12,'From the days of John the Baptist until now, the kingdom of heaven has been subject to violence, and the violent lay claim to it.',NULL),
('bsb','MAT',11,13,'For all the Prophets and the Law prophesied until John.',NULL),
('bsb','MAT',11,14,'And if you are willing to accept it, he is the Elijah who was to come.',NULL),
('bsb','MAT',11,15,'He who has ears, let him hear.',NULL),
('bsb','MAT',11,16,'To what can I compare this generation? They are like children sitting in the marketplaces and calling out to others:',NULL),
('bsb','MAT',11,17,'‘We played the flute for you, and you did not dance; we sang a dirge, and you did not mourn.’',NULL),
('bsb','MAT',11,18,'For John came neither eating nor drinking, and they say, ‘He has a demon!’',NULL),
('bsb','MAT',11,19,'The Son of Man came eating and drinking, and they say, ‘Look at this glutton and drunkard, a friend of tax collectors and sinners!’ But wisdom is vindicated by her actions.”',NULL),
('bsb','MAT',11,20,'Then Jesus began to denounce the cities in which most of His miracles had been performed, because they did not repent.',NULL),
('bsb','MAT',11,21,'“Woe to you, Chorazin! Woe to you, Bethsaida! For if the miracles that were performed in you had been performed in Tyre and Sidon, they would have repented long ago in sackcloth and ashes.',NULL),
('bsb','MAT',11,22,'But I tell you, it will be more bearable for Tyre and Sidon on the day of judgment than for you.',NULL),
('bsb','MAT',11,23,'And you, Capernaum, will you be lifted up to heaven? No, you will be brought down to Hades! For if the miracles that were performed in you had been performed in Sodom, it would have remained to this day.',NULL),
('bsb','MAT',11,24,'But I tell you that it will be more bearable for Sodom on the day of judgment than for you.”',NULL),
('bsb','MAT',11,25,'At that time Jesus declared, “I praise You, Father, Lord of heaven and earth, because You have hidden these things from the wise and learned, and revealed them to little children.',NULL),
('bsb','MAT',11,26,'Yes, Father, for this was well-pleasing in Your sight.',NULL),
('bsb','MAT',11,27,'All things have been entrusted to Me by My Father. No one knows the Son except the Father, and no one knows the Father except the Son and those to whom the Son chooses to reveal Him.',NULL),
('bsb','MAT',11,28,'Come to Me, all you who are weary and burdened, and I will give you rest.',NULL),
('bsb','MAT',11,29,'Take My yoke upon you and learn from Me; for I am gentle and humble in heart, and you will find rest for your souls.',NULL),
('bsb','MAT',11,30,'For My yoke is easy and My burden is light.”',NULL),
('bsb','MAT',17,1,'After six days Jesus took with Him Peter, James, and John the brother of James, and led them up a high mountain by themselves.',NULL),
('bsb','MAT',17,2,'There He was transfigured before them. His face shone like the sun, and His clothes became as white as the light.',NULL),
('bsb','MAT',17,3,'Suddenly Moses and Elijah appeared before them, talking with Jesus.',NULL),
('bsb','MAT',17,4,'Peter said to Jesus, “Lord, it is good for us to be here. If You wish, I will put up three shelters —one for You, one for Moses, and one for Elijah.”',NULL),
('bsb','MAT',17,5,'While Peter was still speaking, a bright cloud enveloped them, and a voice from the cloud said, “This is My beloved Son, in whom I am well pleased. Listen to Him!”',NULL),
('bsb','MAT',17,6,'When the disciples heard this, they fell facedown in terror.',NULL),
('bsb','MAT',17,7,'Then Jesus came over and touched them. “Get up,” He said. “Do not be afraid.”',NULL),
('bsb','MAT',17,8,'And when they looked up, they saw no one except Jesus.',NULL),
('bsb','MAT',17,9,'As they were coming down the mountain, Jesus commanded them, “Do not tell anyone about this vision until the Son of Man has been raised from the dead.”',NULL),
('bsb','MAT',17,10,'The disciples asked Him, “Why then do the scribes say that Elijah must come first?”',NULL),
('bsb','MAT',17,11,'Jesus replied, “Elijah does indeed come, and he will restore all things.',NULL),
('bsb','MAT',17,12,'But I tell you that Elijah has already come, and they did not recognize him, but have done to him whatever they wished. In the same way, the Son of Man will suffer at their hands.”',NULL),
('bsb','MAT',17,13,'Then the disciples understood that He was speaking to them about John the Baptist.',NULL),
('bsb','MAT',17,14,'When they came to the crowd, a man came up to Jesus and knelt before Him.',NULL),
('bsb','MAT',17,15,'“Lord, have mercy on my son,” he said. “He has seizures and is suffering terribly. He often falls into the fire or into the water.',NULL),
('bsb','MAT',17,16,'I brought him to Your disciples, but they could not heal him.”',NULL),
('bsb','MAT',17,17,'“O unbelieving and perverse generation!” Jesus replied. “How long must I remain with you? How long must I put up with you? Bring the boy here to Me.”',NULL),
('bsb','MAT',17,18,'Then Jesus rebuked the demon, and it came out of the boy, and he was healed from that moment.',NULL),
('bsb','MAT',17,19,'Afterward the disciples came to Jesus privately and asked, “Why couldn’t we drive it out?”',NULL),
('bsb','MAT',17,20,'“Because you have so little faith,” He answered. “For truly I tell you, if you have faith the size of a mustard seed, you can say to this mountain, ‘Move from here to there,’ and it will move. Nothing will be impossible for you.”',NULL),
('bsb','MAT',17,22,'When they gathered together in Galilee, Jesus told them, “The Son of Man is about to be delivered into the hands of men.',NULL),
('bsb','MAT',17,23,'They will kill Him, and on the third day He will be raised to life.” And the disciples were deeply grieved.',NULL),
('bsb','MAT',17,24,'After they had arrived in Capernaum, the collectors of the two-drachma tax came to Peter and asked, “Does your Teacher pay the two drachmas?”',NULL),
('bsb','MAT',17,25,'“Yes,” he answered. When Peter entered the house, Jesus preempted him. “What do you think, Simon?” He asked. “From whom do the kings of the earth collect customs and taxes: from their own sons, or from others?”',NULL),
('bsb','MAT',17,26,'“From others,” Peter answered. “Then the sons are exempt,” Jesus declared.',NULL),
('bsb','MAT',17,27,'“But so that we may not offend them, go to the sea, cast a hook, and take the first fish you catch. When you open its mouth, you will find a four-drachma coin. Take it and give it to them for My tax and yours.”',NULL),
('bsb','JHN',3,1,'Now there was a man of the Pharisees named Nicodemus, a leader of the Jews.',NULL),
('bsb','JHN',3,2,'He came to Jesus at night and said, “Rabbi, we know that You are a teacher who has come from God. For no one could perform the signs You are doing if God were not with him.”',NULL),
('bsb','JHN',3,3,'Jesus replied, “Truly, truly, I tell you, no one can see the kingdom of God unless he is born again.”',NULL),
('bsb','JHN',3,4,'“How can a man be born when he is old?” Nicodemus asked. “Can he enter his mother’s womb a second time to be born?”',NULL),
('bsb','JHN',3,5,'Jesus answered, “Truly, truly, I tell you, no one can enter the kingdom of God unless he is born of water and the Spirit.',NULL),
('bsb','JHN',3,6,'Flesh is born of flesh, but spirit is born of the Spirit.',NULL),
('bsb','JHN',3,7,'Do not be amazed that I said, ‘You must be born again.’',NULL),
('bsb','JHN',3,8,'The wind blows where it wishes. You hear its sound, but you do not know where it comes from or where it is going. So it is with everyone born of the Spirit.”',NULL),
('bsb','JHN',3,9,'“How can this be?” Nicodemus asked.',NULL),
('bsb','JHN',3,10,'“You are Israel’s teacher,” said Jesus, “and you do not understand these things?',NULL),
('bsb','JHN',3,11,'Truly, truly, I tell you, we speak of what we know, and we testify to what we have seen, and yet you people do not accept our testimony.',NULL),
('bsb','JHN',3,12,'If I have told you about earthly things and you do not believe, how will you believe if I tell you about heavenly things?',NULL),
('bsb','JHN',3,13,'No one has ascended into heaven except the One who descended from heaven—the Son of Man.',NULL),
('bsb','JHN',3,14,'Just as Moses lifted up the snake in the wilderness, so the Son of Man must be lifted up,',NULL),
('bsb','JHN',3,15,'that everyone who believes in Him may have eternal life.',NULL),
('bsb','JHN',3,16,'For God so loved the world that He gave His one and only Son, that everyone who believes in Him shall not perish but have eternal life.',NULL),
('bsb','JHN',3,17,'For God did not send His Son into the world to condemn the world, but to save the world through Him.',NULL),
('bsb','JHN',3,18,'Whoever believes in Him is not condemned, but whoever does not believe has already been condemned, because he has not believed in the name of God’s one and only Son.',NULL),
('bsb','JHN',3,19,'And this is the verdict: The Light has come into the world, but men loved the darkness rather than the Light because their deeds were evil.',NULL),
('bsb','JHN',3,20,'Everyone who does evil hates the Light, and does not come into the Light for fear that his deeds will be exposed.',NULL),
('bsb','JHN',3,21,'But whoever practices the truth comes into the Light, so that it may be seen clearly that what he has done has been accomplished in God.”',NULL),
('bsb','JHN',3,22,'After this, Jesus and His disciples went into the Judean countryside, where He spent some time with them and baptized.',NULL),
('bsb','JHN',3,23,'Now John was also baptizing at Aenon near Salim, because the water was plentiful there, and people kept coming to be baptized.',NULL),
('bsb','JHN',3,24,'(For John had not yet been thrown into prison.)',NULL),
('bsb','JHN',3,25,'Then a dispute arose between John’s disciples and a certain Jew over the issue of ceremonial washing.',NULL),
('bsb','JHN',3,26,'So John’s disciples came to him and said, “Look, Rabbi, the One who was with you beyond the Jordan, the One you testified about—He is baptizing, and everyone is going to Him.”',NULL),
('bsb','JHN',3,27,'John replied, “A man can receive only what is given him from heaven.',NULL),
('bsb','JHN',3,28,'You yourselves can testify that I said, ‘I am not the Christ, but am sent ahead of Him.’',NULL),
('bsb','JHN',3,29,'The bride belongs to the bridegroom. The friend of the bridegroom stands and listens for him, and is overjoyed to hear the bridegroom’s voice. That joy is mine, and it is now complete.',NULL),
('bsb','JHN',3,30,'He must increase; I must decrease.',NULL),
('bsb','JHN',3,31,'The One who comes from above is above all. The one who is from the earth belongs to the earth and speaks as one from the earth. The One who comes from heaven is above all.',NULL),
('bsb','JHN',3,32,'He testifies to what He has seen and heard, yet no one accepts His testimony.',NULL),
('bsb','JHN',3,33,'Whoever accepts His testimony has certified that God is truthful.',NULL),
('bsb','JHN',3,34,'For the One whom God has sent speaks the words of God, for God gives the Spirit without limit.',NULL),
('bsb','JHN',3,35,'The Father loves the Son and has placed all things in His hands.',NULL),
('bsb','JHN',3,36,'Whoever believes in the Son has eternal life. Whoever rejects the Son will not see life. Instead, the wrath of God remains on him.”',NULL),
('bsb','3JN',1,1,'The elder, To the beloved Gaius, whom I love in the truth:',NULL),
('bsb','3JN',1,2,'Beloved, I pray that in every way you may prosper and enjoy good health, as your soul also prospers.',NULL),
('bsb','3JN',1,3,'For I was overjoyed when the brothers came and testified about your devotion to the truth, in which you continue to walk.',NULL),
('bsb','3JN',1,4,'I have no greater joy than to hear that my children are walking in the truth.',NULL),
('bsb','3JN',1,5,'Beloved, you are faithful in what you are doing for the brothers, and especially since they are strangers to you.',NULL),
('bsb','3JN',1,6,'They have testified to the church about your love. You will do well to send them on their way in a manner worthy of God.',NULL),
('bsb','3JN',1,7,'For they went out on behalf of the Name, accepting nothing from the Gentiles.',NULL),
('bsb','3JN',1,8,'Therefore we ought to support such men, so that we may be fellow workers for the truth.',NULL),
('bsb','3JN',1,9,'I have written to the church about this, but Diotrephes, who loves to be first, will not accept our instruction.',NULL),
('bsb','3JN',1,10,'So if I come, I will call attention to his malicious slander against us. And unsatisfied with that, he refuses to welcome the brothers and forbids those who want to do so, even putting them out of the church.',NULL),
('bsb','3JN',1,11,'Beloved, do not imitate what is evil, but what is good. The one who does good is of God; the one who does evil has not seen God.',NULL),
('bsb','3JN',1,12,'Demetrius has received a good testimony from everyone, and from the truth itself. We also testify for him, and you know that our testimony is true.',NULL),
('bsb','3JN',1,13,'I have many things to write to you, but I would prefer not to do so with pen and ink.',NULL),
('bsb','3JN',1,14,'Instead, I hope to see you soon and speak with you face to face. Peace to you. The friends here send you greetings. Greet each of our friends there by name.',NULL),
('bsb','REV',12,1,'And a great sign appeared in heaven: a woman clothed in the sun, with the moon under her feet and a crown of twelve stars on her head.',NULL),
('bsb','REV',12,2,'She was pregnant and crying out in the pain and agony of giving birth.',NULL),
('bsb','REV',12,3,'Then another sign appeared in heaven: a huge red dragon with seven heads, ten horns, and seven royal crowns on his heads.',NULL),
('bsb','REV',12,4,'His tail swept a third of the stars from the sky, tossing them to the earth. And the dragon stood before the woman who was about to give birth, ready to devour her child as soon as she gave birth.',NULL),
('bsb','REV',12,5,'And she gave birth to a son, a male child, who will rule all the nations with an iron scepter. And her child was caught up to God and to His throne.',NULL),
('bsb','REV',12,6,'And the woman fled into the wilderness, where God had prepared a place for her to be nourished for 1,260 days.',NULL),
('bsb','REV',12,7,'Then a war broke out in heaven: Michael and his angels fought against the dragon, and the dragon and his angels fought back.',NULL),
('bsb','REV',12,8,'But the dragon was not strong enough, and no longer was any place found in heaven for him and his angels.',NULL),
('bsb','REV',12,9,'And the great dragon was hurled down—that ancient serpent called the devil and Satan, the deceiver of the whole world. He was hurled to the earth, and his angels with him.',NULL),
('bsb','REV',12,10,'And I heard a loud voice in heaven saying: “Now have come the salvation and the power and the kingdom of our God, and the authority of His Christ. For the accuser of our brothers has been thrown down— he who accuses them day and night before our God.',NULL),
('bsb','REV',12,11,'They have conquered him by the blood of the Lamb and by the word of their testimony. And they did not love their lives so as to shy away from death.',NULL),
('bsb','REV',12,12,'Therefore rejoice, O heavens, and you who dwell in them! But woe to the earth and the sea; with great fury the devil has come down to you, knowing he has only a short time.”',NULL),
('bsb','REV',12,13,'And when the dragon saw that he had been thrown to the earth, he pursued the woman who had given birth to the male child.',NULL),
('bsb','REV',12,14,'But the woman was given two wings of a great eagle to fly from the presence of the serpent to her place in the wilderness, where she was nourished for a time, and times, and half a time.',NULL),
('bsb','REV',12,15,'Then from the mouth of the serpent spewed water like a river to overtake the woman and sweep her away in the torrent.',NULL),
('bsb','REV',12,16,'But the earth helped the woman and opened its mouth to swallow up the river that had poured from the dragon’s mouth.',NULL),
('bsb','REV',12,17,'And the dragon was enraged at the woman, and went to make war with the rest of her children, who keep the commandments of God and hold to the testimony of Jesus. And the dragon stood on the shore of the sea.',NULL);
INSERT INTO chapter_titles (translation_id, book_id, chapter, text) VALUES
('bsb','PSA',23,'A Psalm of David.');
INSERT INTO verses_fts (verses_fts) VALUES ('rebuild');
